- interface DestinoAtualResumo { categoria; abaId; label; subgrupoLabel: string|null; rotulo /* "FII's › Tijolo" */ };
- interface DestinoImportadoItem { bankInvestmentId; portfolioId: string|null; connectionId; banco; nome; ticker: string|null; saldo: number; grupo: 'rv'|'rf'|'fundos'|'previdencia'|'ja-estava'|'sem-suporte' /* faixa do protótipo */; situacao: SituacaoDestino; atual: DestinoAtualResumo|null; via: ViaSugestao|null; confira: boolean; opcoes: MoverOpcoesResponse|null /* só em para-revisar */; texto?: string };
- interface DestinosImportadosResponse { habilitado; itens; paraRevisar: number };
- interface AplicarDestinosResponse { aplicados; semMudanca; confirmados; parcial: boolean; erros: {id; nome; motivo}[]; historicoIds: string[] } e interface AplicarDestinosErro409 { error: string; erros: {id; nome; motivo}[] };
- escolhaValeParaItem(opcoes, categoria, subgrupo?) → {ok:true; subgrupo}|{ok:false; motivo}. Lê só opcoes.destinos; um subgrupo inexistente cai em subgrupoSugerido;
- intersecaoDestinos(lista: MoverOpcoesResponse[]) → {categoria, label, subgrupos: {id, label}[]}[]. Abas com permitido em todos; seções só as comuns a todos;
- rotuloVia(via): 'pelo catálogo da CVM' | 'pelo nome' | 'estratégia padrão' | 'pelo indexador' | 'pelo tipo do título' | 'pelo tipo do fundo'.

